/* Historical replay engine: all temporal rules are independent of presentation. */
(function(root){
const key=m=>[m.date,m.home,m.away].join('|');
let historicalRules={adjustments:[],rules:[],decisions:[]};
function configureRules(data){historicalRules=data||{adjustments:[],rules:[],decisions:[]}}
const teamKey=s=>String(s).normalize('NFKD').toLowerCase().replace(/[\u0300-\u036f]/g,'').normalize('NFC').replace(/\b(fc|cf|ac|as|afc|sc|ss|ssc)\b/g,'').replace(/[^a-z0-9가-힣]/g,'');
function adjustmentsFor(league,season,date,closed=[]){const latest=new Map();for(const a of historicalRules.adjustments||[]){if(a.league!==league||+a.season!==+season||a.date>date||(a.date===date&&!closed.includes(date)))continue;let k=a.case+'|'+a.team,old=latest.get(k);if(!old||old.date<a.date)latest.set(k,a)}return [...latest.values()]}
function rulesFor(league,season){return (historicalRules.rules||[]).filter(r=>r.league===league&&season>=r.from&&season<=(r.to??9999)).at(-1)||{sort:league.split('-')[0]==='england'&&season<1976?'goal-average':'goal-difference',coverage:'basic'}}
function completed(m,date,closed,watched){return m.date<date||(m.date===date&&(closed.includes(date)||watched.includes(key(m))))}
function winPoints(league,season){league=league.split('-')[0];if(league==='england')return season>=1981?3:2;if(league==='spain'||league==='germany')return season>=1995?3:2;if(league==='italy')return season>=1994?3:2;if(league==='france')return season>=1994||season===1988?3:2;if(['holland','portugal','belgium'].includes(league))return season>=1995?3:2;if(league==='scotland')return season>=1994?3:2;if(league==='greece')return season>=1992?3:2;if(league==='turkey')return season>=1987?3:2;return 3}
function table(matches,options={}){const {date='9999',closed=[],watched=[],league='',season=2026,points=winPoints(league,season),live=[]}=options;const teams={};for(const m of matches){for(const n of [m.home,m.away])teams[n]??={name:n,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0,form:[]}}
let used=matches.filter(m=>completed(m,date,closed,watched));if(live.length){const ids=new Set(live.map(key));used=used.filter(m=>!ids.has(key(m))).concat(live)}for(const m of used){if(!teams[m.home]||!teams[m.away])continue;let a=teams[m.home],b=teams[m.away];a.p++;b.p++;a.gf+=m.hg;a.ga+=m.ag;b.gf+=m.ag;b.ga+=m.hg;if(m.hg>m.ag){a.w++;b.l++;a.pts+=points;a.form.push('W');b.form.push('L')}else if(m.hg<m.ag){b.w++;a.l++;b.pts+=points;a.form.push('L');b.form.push('W')}else{a.d++;b.d++;a.pts++;b.pts++;a.form.push('D');b.form.push('D')}}
// France used an additional scoring bonus before returning to ordinary points.
if(league==='france'&&[1973,1974,1975].includes(+season))for(const m of used){if(+season===1973){if(m.hg>=3)teams[m.home].pts++;if(m.ag>=3)teams[m.away].pts++}else{if(m.hg-m.ag>=3)teams[m.home].pts++;if(m.ag-m.hg>=3)teams[m.away].pts++}}
for(const t of Object.values(teams)){t.rawPts=t.pts;t.adjustment=0;t.adjustments=[]}
for(const a of adjustmentsFor(league,season,date,closed)){let t=Object.values(teams).find(t=>[a.team,...(a.aliases||[])].some(s=>teamKey(s)===teamKey(t.name)));if(t){t.pts+=a.points;t.adjustment+=a.points;t.adjustments.push(a)}}
const rule=rulesFor(league,season),ratio=rule.sort==='goal-average';let rows=Object.values(teams).map(t=>({...t,gd:t.gf-t.ga,ratio:t.ga?t.gf/t.ga:(t.gf?Infinity:0),ruleCoverage:rule.coverage||'core'}));
const groups=new Map();for(const r of rows){let g=groups.get(r.pts)||[];g.push(r);groups.set(r.pts,g)}
if(rule.sort==='head-to-head')for(const group of groups.values())if(group.length>1){let names=new Set(group.map(t=>t.name)),scheduled=matches.filter(m=>names.has(m.home)&&names.has(m.away)),met=used.filter(m=>names.has(m.home)&&names.has(m.away));let completePairs=scheduled.length>=group.length*(group.length-1)&&scheduled.every(m=>completed(m,date,closed,watched));for(const t of group){t.headToHeadReady=completePairs;t.h2hPts=0;t.h2hGd=0}if(completePairs)for(const m of met){let a=group.find(t=>t.name===m.home),b=group.find(t=>t.name===m.away);a.h2hGd+=m.hg-m.ag;b.h2hGd+=m.ag-m.hg;if(m.hg>m.ag)a.h2hPts+=points;else if(m.hg<m.ag)b.h2hPts+=points;else{a.h2hPts++;b.h2hPts++}}}
function compare(a,b){return b.pts-a.pts||(rule.sort==='wins'?b.w-a.w:0)||(rule.sort==='goals-for'?b.gf-a.gf:0)||(rule.sort==='head-to-head'&&a.headToHeadReady&&b.headToHeadReady?(b.h2hPts-a.h2hPts||b.h2hGd-a.h2hGd):0)||(ratio?b.ratio-a.ratio:b.gd-a.gd)||b.gf-a.gf}
rows.sort((a,b)=>compare(a,b)||a.name.localeCompare(b.name));for(let i=0;i<rows.length;i++){let tied=i>0&&compare(rows[i-1],rows[i])===0;rows[i].rank=tied?rows[i-1].rank:i+1;rows[i].tieUnresolved=tied;if(tied)rows[i-1].tieUnresolved=true}
if(league==='italy'&&season>=2022&&matches.every(m=>completed(m,date,closed,watched))&&rows[0]?.pts===rows[1]?.pts){rows[0].titlePlayoffRequired=true;rows[1].titlePlayoffRequired=true;rows[0].rank=rows[1].rank=1}
return rows}
function minute(s){let a=String(s).split('+').map(Number);return (a[0]||0)+(a[1]||0)*.01}
function scoreAt(m,at){const g=(m.goals||[]).filter(g=>minute(g.minute)<=at);return [g.filter(g=>g.team===m.home).length,g.filter(g=>g.team===m.away).length]}
function canName(m,matches,date,closed,watched){if(m.date<=date)return true;if(m.group||/group|league|matchday|round 1|prelim/i.test(m.stage||''))return true;const stages=[...new Set(matches.filter(x=>!x.group).map(x=>x.stage))];let i=stages.indexOf(m.stage);if(i<0)return false;if(i===0){const gs=matches.filter(x=>x.group);return !gs.length||gs.every(x=>completed(x,date,closed,watched))}const prev=matches.filter(x=>x.stage===stages[i-1]);return prev.length>0&&prev.every(x=>completed(x,date,closed,watched))}
const api={key,completed,winPoints,table,minute,scoreAt,canName,configureRules,adjustmentsFor,rulesFor};root.ReplayEngine=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
